-- World Transplant Games swimming records imported from wtg_records.json.
create table if not exists public.world_records (
  id text primary key,
  event text not null,
  age_group text,
  time text not null,
  athlete_name text not null,
  country text not null,
  games text not null,
  gender text not null,
  category text not null,
  course text not null default 'LCM',
  source_organisation text not null,
  source_document text not null,
  source_url text not null,
  record_type text not null,
  pool_type text not null,
  imported_at timestamptz not null default now()
);

alter table public.world_records enable row level security;
drop policy if exists "Public can view world records" on public.world_records;
create policy "Public can view world records"
  on public.world_records for select to anon, authenticated using (true);
grant select on public.world_records to anon, authenticated;

on conflict (id) do update set
  event = excluded.event,
  age_group = excluded.age_group,
  time = excluded.time,
  athlete_name = excluded.athlete_name,
  country = excluded.country,
  games = excluded.games,
  gender = excluded.gender,
  category = excluded.category,
  course = excluded.course,
  source_organisation = excluded.source_organisation,
  source_document = excluded.source_document,
  source_url = excluded.source_url,
  record_type = excluded.record_type,
  pool_type = excluded.pool_type,
  imported_at = now();
